current AS (SELECT "id", COALESCE("catalogs",'{}'::jsonb) AS catalogs FROM "SiteSettings" WHERE "id"='default')
UPDATE "SiteSettings" s
SET "catalogs" = jsonb_set(
  jsonb_set(
    current.catalogs,
    '{componentBrands}',
    COALESCE((
      SELECT jsonb_agg(item ORDER BY item->>'category', item->>'name')
      FROM (
        SELECT DISTINCT ON (lower(item->>'category'), lower(item->>'name')) item
        FROM (
          SELECT jsonb_array_elements(COALESCE(current.catalogs->'componentBrands','[]'::jsonb)) AS item
          UNION ALL
          SELECT jsonb_array_elements((seed.data->'brands')) AS item
        ) all_items
        ORDER BY lower(item->>'category'), lower(item->>'name'), CASE WHEN item->>'sourceType' IS NULL THEN 0 ELSE 1 END
      ) deduped
    ), '[]'::jsonb),
    true
  ),
  '{componentModels}',
  COALESCE((
    SELECT jsonb_agg(item ORDER BY item->>'category', item->>'brand', item->>'model')
    FROM (
      SELECT DISTINCT ON (lower(item->>'category'), lower(item->>'brand'), lower(item->>'model')) item
      FROM (
        SELECT jsonb_array_elements(COALESCE(current.catalogs->'componentModels','[]'::jsonb)) AS item
        UNION ALL
        SELECT jsonb_array_elements((seed.data->'models')) AS item
      ) all_items
      ORDER BY lower(item->>'category'), lower(item->>'brand'), lower(item->>'model'), CASE WHEN item->>'sourceType' IS NULL THEN 0 ELSE 1 END
    ) deduped
  ), '[]'::jsonb),
  true
)
FROM current, seed
WHERE s."id"=current."id";
